CREATE TABLE "insite"."install_reports" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"          bigint                   NOT NULL,
  "details"         jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "submitted_by"    text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "idempotency_key" uuid,
  CONSTRAINT "install_reports_idempotency_key_key" UNIQUE (idempotency_key),
  CONSTRAINT "install_reports_pkey" PRIMARY KEY (id),
  CONSTRAINT "install_reports_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE
);

ALTER TABLE "insite"."install_reports"
  ENABLE ROW LEVEL SECURITY;

CREATE INDEX idx_install_reports_details_gin ON insite.install_reports USING gin (details);

CREATE INDEX idx_install_reports_job_id ON insite.install_reports USING btree (job_id);

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON insite.install_reports
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable insert for authenticated users" ON "insite"."install_reports"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable read access for authenticated users" ON "insite"."install_reports"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for authenticated users" ON "insite"."install_reports"
  FOR UPDATE
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text))
  WITH CHECK ((auth.role() = 'authenticated'::text));

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "insite"."install_reports" TO "anon", "authenticated", "service_role";
